function splitKey(key) {
  const segments = String(key || "").split(":");
  if (segments[0] === "nexus" && segments.length > 2) {
    return [segments[1], segments.slice(2).join(":")];
  }
  return [segments[0], segments.slice(1).join(":")];
}

function requireCapability(root, key) {
  const [family, operation] = splitKey(key);
  const capability = root?.[family]?.[operation];
  if (!capability) throw new Error(`IPC_CONTRACT_UNKNOWN:${family}.${operation}`);
  return capability;
}

export function invokeCoreCapability(key, ...args) {
  return requireCapability(window.nexus.core, key)(...args);
}

export function sendCoreEvent(key, ...args) {
  return requireCapability(window.nexus.events, key).send(...args);
}

export function onCoreEvent(key, listener) {
  return requireCapability(window.nexus.events, key).on(listener);
}

export function offCoreEvent(key, listener) {
  return requireCapability(window.nexus.events, key).off(listener);
}
